# Account, quote validation and post-payment onboarding wireframes.
def panel(title,body,actions=''):
    return f'<section class="paper-panel"><h2>{title}</h2>{body}<div class="actions">{actions}</div></section>'

def resume_card():
    return panel('Your application is waiting for you.','<p><span class="chip">Mock payment confirmed</span></p><h3>Health application · DEMO-01</h3><p>Next: confirm your details and finish disclosures.</p>',a('onboarding.html','Resume onboarding')+a('timeline.html','View timeline','text-link'))

shell('home-signed-in.html','Your cover and applications',heading('YOUR ACCOUNT','Pick up where you left off.','View your applications and policy records in one place.')+resume_card()+panel('Your policy records','<p>Check the policy document, effective dates and support options.</p>',a('policy.html','Open example policy','button secondary'))+'<section id="categories" class="section"><h2>Explore another kind of cover</h2><div class="category-grid">'+cards+'</div></section>','SCR-001/SIGNED-IN',[1,11,26],1,False,'Signed in')
for ck,cv in categories.items():
    shell(ck+'-signed-in.html',cv['name']+' account homepage',heading('YOUR ACCOUNT / '+cv['name'].upper(),'Continue your application.')+resume_card().replace('Health application',cv['name']+' application')+panel('Explore '+cv['name'].lower()+' cover','<p>Review product details, scenario assumptions and source dates.</p>',a(ck+'.html','Browse '+cv['name'].lower(),'button secondary')),'SCR-003/SIGNED-IN',[1,26,cv['issue']],1,False,'Signed in')

shell('login.html','Log in and keep your quote',heading('YOUR ACCOUNT','Continue with your quote.','Log in before payment. Your selected quote stays with you.')+f'''<div class="two-column"><section class="document"><h2>Log in</h2><label for="login-email">Email address</label><input id="login-email" type="email" placeholder="Your email" autocomplete="off"><button disabled>Send sign-in link</button><p class="hint">Authentication layout only; no email is sent.</p><hr><div class="actions">{a('quote-review.html','Preview signed-in quote review')}{a('home-signed-in.html','Already started? Open your account','button secondary')}</div></section><aside class="sticky-panel"><h2>Your selection is saved for this step.</h2><p>After login, we check the current quote and ask you to review any changes before payment.</p><p>Already bought a plan? Your account shows its application or policy status.</p>{a('summary.html','Back to your summary','text-link')}</aside></div>''','SCR-LOGIN',[11,26,31],3,True)

shell('quote-scenarios.html','Quote scenario coverage',heading('QUOTE SOURCES','520 targets. Every assumption recorded.','A target is not a collected quote. Use exact source-verified scenarios before a payable total exists.')+"""<div class="table-wrap"><table><thead><tr><th>Product</th><th>Core scenario matrix</th><th>Candidate captures</th></tr></thead><tbody><tr><th>Term life</th><td>5 ages × 3 cover levels × 2 smoking statuses</td><td>30 × 5 insurers = 150</td></tr><tr><th>Health</th><td>5 household profiles × 2 PINs × 3 sum-insured levels</td><td>30 × 5 = 150</td></tr><tr><th>Motor</th><td>5 exact vehicle fixtures × 2 PIN/RTO regions × 3 cover configurations</td><td>30 × 4 = 120</td></tr><tr><th>ULIP</th><td>5 ages × 2 contribution budgets × 2 payment terms</td><td>20 × 5 = 100</td></tr></tbody></table></div>"""+notice('520 candidate captures · source collection','Eligible plan, variant, channel, exact input details and source version are recorded separately. Add-ons and bundles use linked configurations; unsupported combinations remain unavailable.','yellow')+panel('Know what the evidence means','<p>Scenario quote, advertised illustration, published rate table and unquoted target are distinct. Source-defined eligibility and taxes must be complete before payment.</p><p>Life: Tata AIA, HDFC Life, Axis Max Life, Bajaj Life and ICICI Prudential. Health: Tata AIG, HDFC ERGO, Niva Bupa, Bajaj General and ICICI Lombard. Motor excludes Niva Bupa from this candidate list.</p>',a('published-illustrations.html','Published illustrations','button secondary')+a('addons.html','Add-ons and bundles','text-link')),'SCR-QUOTE/SCOPE',[6,9,22],1,True)

shell('published-illustrations.html','Published premium illustrations',heading('SOURCE-DATED / 10 SEP 2026','Published examples, with the small print.','These are insurer-advertised illustrations. Their profiles differ; they are not comparable personalised quotes.')+'''<div class="question-grid"><article class="paper-panel"><span class="chip">Published illustration</span><h2>Tata AIA</h2><h3>₹501 / month</h3><p>Sampoorna Raksha Promise · Life Promise option. Female20, nonsmoker, standard life, ₹1 crore cover,20-year policy, regular pay. First-year digital10% and salaried8.5% discounts.</p><p>Tax completeness needs confirmation. No payable quote is created from this illustration.</p><a href="https://www.tataaia.com/calculator/term-insurance-calculator.html">Official source and assumptions ↗</a></article><article class="paper-panel"><span class="chip">Published illustration</span><h2>HDFC Life</h2><h3>₹573 / month</h3><p>Click 2 Protect Supreme Plus · Life option. Male20, nonsmoker, salaried,25-year policy, regular monthly pay. First-year15% online discount; taxes and levies excluded.</p><p>Confirm the complete benefit illustration and cover amount before quoting.</p><a href="https://www.hdfclife.com/">Official source and assumptions ↗</a></article></div><p>No insurer partnership is implied. Source capture date is not a price-validity guarantee.</p><a class="button secondary" href="quote-scenarios.html">View supported scenario plan</a>''','SCR-QUOTE/ILLUSTRATIONS',[9,22,38],2,True)

shell('quote-review.html','Review the authoritative quote',heading('BEFORE PAYMENT','One final check of the quote.','Your account is signed in. The selected scenario and source version are checked before payment.')+notice('No complete scenario quote loaded','The payable amount remains unavailable until the sourced scenario, taxes, fees and current terms are verified.','yellow')+'''<div class="two-column"><article class="document"><h2>What is being checked</h2><dl class="definition-list"><div><dt>Profile and PIN code</dt><dd>Exact match to the selected supported scenario</dd></div><div><dt>Quote and terms version</dt><dd>Same version shown in your summary</dd></div><div><dt>Displayed / current total</dt><dd>Unavailable · source quote required</dd></div></dl><button disabled>Confirm amount and continue</button></article><aside class="sticky-panel"><h2>If something changed</h2><p>You will see both amounts and any changed terms. A change above ₹1 stops this step for review. No increase is added silently.</p><p>Different details or PIN code require a new quote; the ₹1 check does not apply across different profiles.</p><a class="button secondary" href="payment.html">Preview mock Juspay checkout</a></aside></div>''','SCR-QUOTE/VALIDATE',[9,31],3,True)

shell('payment.html','Mock Juspay checkout',heading('PAYMENT / MOCK JUSPAY','Complete payment, then onboarding.','No money moves in this preview. Payment does not activate insurance.')+f'''<div class="two-column"><section class="document"><span class="chip">Mock gateway</span><h2>Order summary</h2><dl class="definition-list"><div><dt>Quote total</dt><dd>Source quote required</dd></div><div><dt>Payment methods</dt><dd>UPI / card layout · no credentials collected</dd></div><div><dt>After confirmation</dt><dd>Complete details, documents and disclosures</dd></div></dl><button disabled>Pay verified amount</button><p class="hint">Real payment is unavailable. Use a simulated outcome to review the flow.</p>{a('quote-review.html','Back to quote review','text-link')}</section><aside class="sticky-panel"><h2>Choose a mock outcome</h2><div class="stack-actions">{a('payment-received.html','Payment confirmed →')}{a('payment-unknown.html','Pending verification','button secondary')}{a('payment-failed.html','Payment failed','button secondary')}</div></aside></div>''','SCR-007/PAYMENT',[4,12,31,32],3,True)

shell('payment-received.html','Payment confirmed — finish onboarding',heading('PAYMENT CONFIRMED / SIMULATED','Next, let’s finish your application.','Your mock payment is confirmed. Your policy has not been issued.')+notice('Onboarding is ready','Complete your details, disclosures and documents. You can return later from your account.','blue')+panel('Your next step','<p>Check the details used for your initial quote. If you change them, we will show a new quote and any balance payment or refund.</p>',a('onboarding.html','Start onboarding')+a('home-signed-in.html','Go to your account','button secondary')),'SCR-007/CONFIRMED',[3,4,27,32],4,True)

shell('onboarding.html','Post-payment onboarding',heading('YOUR APPLICATION / PAYMENT CONFIRMED','A few clear steps from here.','Save your progress and come back when you are ready.')+f'''<div class="two-column"><section class="document"><h2>Your checklist</h2><ol class="timeline checklist"><li class="active"><div><h3>1. Check your original details</h3><p>Review the information and PIN code used for the quote.</p>{a('details-review.html','Review and edit details','button secondary')}</div></li><li><div><h3>2. Confirm documents and nominee</h3><p>Enter details manually or review suggested fields from a document.</p>{a('extraction.html','Preview document assistance','button secondary')}</div></li><li><div><h3>3. Complete disclosures</h3><p>Answer each applicable question. Keep uncertain answers open for help.</p>{a('proposal.html','Open disclosures','button secondary')}</div></li><li><div><h3>4. Review and submit</h3><p>Confirm the exact answers and any revised quote.</p>{a('review.html','Open final review','button secondary')}</div></li></ol></section><aside class="sticky-panel"><span class="chip">Mock paid application</span><h2>Your place is saved.</h2><p>Resume from the website or product homepage after login. Information already confirmed will be shown for reuse.</p>{a('home-signed-in.html','Save and return to account','button secondary')}{a('help.html','I need help with a question','text-link')}</aside></div>''','SCR-006/ONBOARDING',[3,27,46],4,True)

shell('details-review.html','Review original and changed details',heading('ONBOARDING / YOUR DETAILS','Check what changed.','These fixed example inputs demonstrate a detail change. They are not a real customer quote.')+'''<div class="table-wrap"><table><thead><tr><th>Rating input</th><th>Used for initial quote</th><th>Current answer</th></tr></thead><tbody><tr><th>PIN code</th><td>400001</td><td><label for="edited-pin">Updated PIN</label><input id="edited-pin" inputmode="numeric" maxlength="6" value="560001"><strong>Changed · new quote required</strong></td></tr><tr><th>Age / family</th><td>Fixed example profile</td><td>Unchanged</td></tr><tr><th>Disclosures</th><td>Initial recorded answers</td><td>Review every applicable question</td></tr></tbody></table></div>'''+notice('Review the new quote before continuing','A PIN or other rating-input change may change eligibility, premium or terms. The original answers and payment remain in your history.','yellow')+'<div class="actions">'+a('repricing.html','Preview new quote review')+a('quote-unavailable.html','Preview unsupported PIN / profile','button secondary')+a('onboarding.html','Keep current draft','text-link')+'</div>','SCR-006/DETAIL-CHANGE',[3,9,27,30],4,True)

shell('repricing.html','Review premium difference',heading('REVISED QUOTE / DETAIL CHANGE','A new detail. A new quote to review.','Compare the original details, new details and cost before deciding.')+notice('Arithmetic fixture only','The amounts below test payment and refund behavior. They are not insurer prices or an offer.','yellow')+'''<div class="table-wrap"><table><thead><tr><th>Item</th><th>Original</th><th>Revised</th></tr></thead><tbody><tr><th>PIN code</th><td>400001</td><td>560001</td></tr><tr><th>Total premium fixture</th><td>₹10,000</td><td>₹11,200</td></tr><tr><th>Confirmed net payment</th><td>₹10,000</td><td>₹10,000</td></tr><tr><th>Additional amount</th><td>—</td><td><strong>₹1,200</strong></td></tr></tbody></table></div><section class="paper-panel"><h2>Review all the differences</h2><p>The source, terms and changed answers must accompany the new price. A changed profile is outside the unchanged-quote ₹1 target.</p><label class="check"><input type="checkbox"> I have reviewed the revised details, price and terms.</label><div class="actions"><a href="balance-payment.html" class="button">Preview accepted balance payment</a><a href="refund.html" class="button secondary">Preview a price reduction</a><a href="details-review.html" class="text-link">Edit details</a></div></section>''','SCR-007/REPRICE',[9,12,30],4,True)

shell('balance-payment.html','Additional mock payment',heading('PAYMENT / PREMIUM DIFFERENCE','Pay the accepted difference.','Arithmetic fixture · no real money or insurer quote.')+panel('Additional amount: ₹1,200','<p>Revised total ₹11,200 minus confirmed net paid ₹10,000. The original payment is retained.</p><p>A pending additional attempt must be checked before starting another.</p>',a('balance-paid.html','Simulate confirmed additional payment')+a('payment-unknown.html','Preview uncertain payment','button secondary')+a('repricing.html','Review the difference','text-link')),'SCR-007/BALANCE',[30,31,32],4,True)
shell('balance-paid.html','Additional payment confirmed',heading('PAYMENT / SIMULATED CONFIRMATION','The difference is recorded.','This arithmetic fixture now has ₹11,200 in confirmed net payments. Your application still needs review and issuance.')+panel('Continue your application','<p>Check your remaining disclosures and confirm the exact answer revision.</p>',a('onboarding.html','Resume onboarding')),'SCR-007/BALANCE-PAID',[30,32],4,True)
for slug,title,desc in [('refund','Refund pending','Revised total ₹9,600 minus confirmed net paid ₹10,000 creates a ₹400 mock refund. Confirmation is still pending.'),('refund-complete','Refund confirmed','The ₹400 mock refund is confirmed. Net paid is now ₹9,600. This does not establish policy issuance.'),('refund-failed','Refund needs attention','The mock refund failed. The ₹400 remains outstanding; no completed refund is shown.'),('refund-unknown','Checking the refund','The mock provider outcome is uncertain. Check the same refund reference before another attempt.')]:
    shell(slug+'.html',title,heading('REFUND / ARITHMETIC FIXTURE',title,'No real refund or insurer entitlement is represented.')+notice('Refund reference MOCK-REFUND-01',desc,'blue' if slug=='refund-complete' else 'yellow')+panel('Keep the payment history together','<p>Original payment, revised quote and refund are separate records. Repeated edits recalculate against confirmed payments and refunds while reserving pending amounts.</p>',a('onboarding.html','Resume application','button secondary')+a('refund-complete.html','Confirmed state','text-link')+a('refund-failed.html','Failed state','text-link')+a('refund-unknown.html','Unknown state','text-link')),'SCR-007/'+slug.upper(),[12,30,32],4,True,title)
shell('quote-unavailable.html','Quote unavailable for changed details',heading('QUOTE / DETAILS CHANGED','We need a quote for these details.','There is no verified snapshot for this PIN code and profile.')+notice('Your paid application is preserved','The previous price cannot be applied to different inputs. Keep the draft, correct the details or ask for a sourced quote.','yellow')+'<div class="actions">'+a('details-review.html','Review details')+a('help.html','Ask for help','button secondary')+'</div>','SCR-QUOTE/UNAVAILABLE',[9,27,30],4,True)

shell('extraction.html','Confirm document suggestions',heading('ONBOARDING / OPTIONAL ASSISTANCE','Less retyping. Every answer stays yours.','Use a fictional document in this preview. You can always enter the details manually.')+'''<div class="two-column"><article class="document"><h2>Suggested fields</h2><dl class="definition-list"><div><dt>Document source</dt><dd>Fictional form · page1</dd></div><div><dt>Suggested name</dt><dd>Demo Buyer <label class="check"><input type="checkbox"> Confirm this field</label></dd></div><div><dt>Suggested PIN</dt><dd>Not confidently extracted <label for="manual-pin">Enter PIN manually</label><input id="manual-pin" maxlength="6" inputmode="numeric"></dd></div></dl><p>Missing information never becomes a negative disclosure. Confirmed rating changes need a new quote.</p><a href="details-review.html" class="button">Review confirmed details</a></article><aside class="sticky-panel"><h2>Stay in control.</h2><p>Suggestions are drafts. Check their source, correct mistakes and leave uncertain fields unresolved. The assistant cannot submit your application or decide coverage.</p><a href="proposal.html" class="button secondary">Use manual entry</a></aside></div>''','SCR-006/EXTRACTION',[8,17,47],4,True)

shell('input-controls.html','Quote inputs and validation',heading('QUOTE DETAILS','A few details to start with.','Choose a supported scenario. The premium depends on these answers.')+'''<section class="document"><fieldset><legend>Who needs cover?</legend><div class="option-chips"><label><input type="radio" name="who" checked><span>Just me</span></label><label><input type="radio" name="who"><span>My family</span></label></div></fieldset><label for="input-name">Full name</label><input id="input-name" maxlength="120" autocomplete="off" placeholder="As recorded in your documents"><p class="hint">Names may include Indian scripts, spaces, apostrophes and hyphens. Use fictional details in this preview.</p><label for="input-dob">Date of birth</label><input id="input-dob" type="date" max="2026-09-10"><p class="hint">Choose a date or type it using your device’s date format.</p><label for="input-pin">PIN code</label><input id="input-pin" inputmode="numeric" maxlength="6" pattern="[1-9][0-9]{5}" value="400001" aria-describedby="pin-location"><p id="pin-location" class="location-result">Mumbai · Maharashtra <span class="chip">Location layout example</span></p><p class="hint">Production city mapping requires source verification. A changed PIN can change the quote.</p><fieldset><legend>Do you smoke?</legend><div class="option-chips"><label><input type="radio" name="smokes"><span>Yes</span></label><label><input type="radio" name="smokes" checked><span>No</span></label></div></fieldset><fieldset><legend>Premium payment frequency</legend><div class="option-chips"><label><input type="radio" name="frequency" checked><span>Yearly</span></label><label><input type="radio" name="frequency"><span>Monthly</span></label></div></fieldset><label for="vehicle-reg">Vehicle registration (motor only)</label><input id="vehicle-reg" maxlength="16" placeholder="For example, MH 01 AB 1234" autocomplete="off"><p class="hint">Standard state and Bharat-series formats need separate validation. A format match does not verify ownership.</p><div class="actions"><a class="button" href="health.html">Preview matching results</a><a class="button secondary" href="pincode-ambiguous.html">Multiple localities</a><a class="text-link" href="pincode-unsupported.html">Unsupported PIN</a></div></section>''','SCR-002/CONTROLS',[18,23,27,39,49],1,True)
shell('pincode-ambiguous.html','Choose a locality',heading('LOCATION','Which locality should we use?','This PIN has more than one mapped locality. Choose the one that matches your address.')+'''<section class="paper-panel"><label for="locality-option">City / locality</label><select id="locality-option"><option>Choose a verified locality</option></select><p class="hint">The master must supply verified locality options. A district name is not silently substituted for a city.</p><a href="input-controls.html" class="button secondary">Review PIN code</a></section>''','SCR-PIN/AMBIGUOUS',[9,19,49],1,True)
shell('pincode-unsupported.html','PIN not yet supported',heading('LOCATION','This PIN is not in our supported area yet.','It may be a valid Indian PIN. We cannot match it to our current verified catalogue.')+notice('Keep your details','Check the digits or ask for help. Your other answers are preserved.','yellow')+'<div class="actions"><a href="input-controls.html" class="button">Review PIN</a><a href="help.html" class="button secondary">Get help</a></div>','SCR-PIN/UNSUPPORTED',[9,19,49],1,True)
